const h = @import("hexdump.zig");
const net = @import("link_network.zig");
const Packet = h.Packet;
pub fn typeName(value: i64) []const u8 {
    return switch (value) {
        1 => "A",
        2 => "NS",
        5 => "CNAME",
        6 => "SOA",
        12 => "PTR",
        15 => "MX",
        16 => "TXT",
        28 => "AAAA",
        else => h.fmt("TYPE{d}", .{value}),
    };
}
pub fn rcodeName(value: i64) []const u8 {
    const names = [_][]const u8{ "NoError", "FormErr", "ServFail", "NXDomain", "NotImp", "Refused" };
    return if (value < 6) names[h.u(value)] else h.fmt("RCODE{d}", .{value});
}
const Reader = struct {
    packet: *Packet,
    bytes: []const u8,
    fn need(self: Reader, position: usize, count: usize) h.DissectionError!void {
        if (position > self.bytes.len or count > self.bytes.len - position) return self.packet.fail("dns: truncated");
    }
    fn integer(self: Reader, position: *usize, count: usize) h.DissectionError!i64 {
        try self.need(position.*, count);
        const value = net.integer(self.bytes, position.*, count);
        position.* += count;
        return value;
    }
    fn name(self: Reader, position: *usize) h.DissectionError![]const u8 {
        var cursor = position.*;
        var end: ?usize = null;
        var pointers: usize = 0;
        var labels: h.Text = .{};
        var first = true;
        while (true) {
            try self.need(cursor, 1);
            const count = self.bytes[cursor];
            if (count == 0) {
                if (end == null) end = cursor + 1;
                break;
            }
            if (count >= 192) {
                try self.need(cursor + 1, 1);
                if (end == null) end = cursor + 2;
                pointers += 1;
                if (pointers > 16) return self.packet.fail("dns: compression loop");
                const target = @as(usize, count - 192) * 256 + self.bytes[cursor + 1];
                if (target >= self.bytes.len) return self.packet.fail("dns: pointer out of range");
                cursor = target;
                continue;
            }
            if (count >= 64) return self.packet.fail("dns: bad label type");
            try self.need(cursor + 1, count);
            if (!first) labels.add(".", .{});
            first = false;
            for (self.bytes[cursor + 1 .. cursor + 1 + count]) |c| {
                if (c >= 33 and c <= 126 and c != 46 and c != 92) labels.add("{c}", .{c}) else labels.add("\\{d:0>3}", .{c});
            }
            cursor += @as(usize, count) + 1;
        }
        position.* = end.?;
        return if (first) "<root>" else labels.value();
    }
    fn ipv6(self: Reader, position: *usize) h.DissectionError![]const u8 {
        var values: [8]i64 = undefined;
        var groups: [8][]const u8 = undefined;
        for (&values, &groups) |*value, *group| {
            value.* = try self.integer(position, 2);
            group.* = h.fmt("{x}", .{value.*});
        }
        var start: ?usize = null;
        var length: usize = 1;
        var i: usize = 0;
        while (i < 8) {
            if (values[i] != 0) {
                i += 1;
                continue;
            }
            var end = i;
            while (end < 8 and values[end] == 0) end += 1;
            if (end - i > length) {
                start = i;
                length = end - i;
            }
            i = end;
        }
        return if (start) |s| h.fmt("{s}::{s}", .{ h.join(groups[0..s], ":"), h.join(groups[s + length ..],
             ":") }) else h.join(&groups, ":");
    }
};
pub fn dissect(p: *Packet, bytes: []const u8) h.DissectionError!void {
    const reader: Reader = .{ .packet = p, .bytes = bytes };
    try reader.need(0, 12);
    var position: usize = 0;
    p.put("dns.id", try reader.integer(&position, 2));
    const flags = try reader.integer(&position, 2);
    p.put("dns.flags", flags);
    p.put("dns.flags.response", (flags >> 15) & 1);
    p.put("dns.flags.opcode", (flags >> 11) & 15);
    p.put("dns.flags.rcode", flags & 15);
    var counts: [4]i64 = undefined;
    for ([_][]const u8{ "queries", "answers", "auth_rr", "add_rr" }, &counts) |name, *count| {
        count.* = try reader.integer(&position, 2);
        p.put(h.fmt("dns.count.{s}", .{name}), count.*);
    }
    for (0..h.u(counts[0])) |_| {
        const name = try reader.name(&position);
        try reader.need(position, 4);
        const type_ = try reader.integer(&position, 2);
        position += 2;
        p.set("dns.qry.name", .{ .text = name }, true);
        p.set("dns.qry.type", .{ .number = type_ }, true);
    }
    for ([_][]const u8{ "dns.answer", "dns.authority", "dns.additional" }, 0..) |section, section_index| for (0..h.u(counts[section_index + 1])) |_| {
        const owner = try reader.name(&position);
        try reader.need(position, 10);
        const type_ = try reader.integer(&position, 2);
        const class = try reader.integer(&position, 2);
        const ttl = try reader.integer(&position, 4);
        const length = h.u(try reader.integer(&position, 2));
        try reader.need(position, length);
        const end = position + length;
        var body: []const u8 = undefined;
        var address: i64 = 0;
        if (type_ == 1) {
            address = try reader.integer(&position, 4);
            body = net.ipv4(address);
        } else if (type_ == 28) body = try reader.ipv6(&position) else if (type_ == 2 or type_ == 5 or type_ == 12) body = try reader.name(&position) else if (type_ == 15) {
            const preference = try reader.integer(&position, 2);
            const name = try reader.name(&position);
            body = h.fmt("{d} {s}", .{ preference, name });
        } else if (type_ == 6) {
            const first = try reader.name(&position);
            const second = try reader.name(&position);
            var text: h.Text = .{};
            text.add("{s} {s}", .{ first, second });
            for (0..5) |_| text.add(" {d}", .{try reader.integer(&position, 4)});
            body = text.value();
        } else {
            body = h.fmt("{d} bytes", .{length});
            position = end;
        }
        if (position != end) return p.fail("dns: bad rdata length");
        p.set(section, .{ .text = h.fmt("{s} {s} {s} {d} {s}", .{ owner, typeName(type_), if (class == 1) "IN" else h.fmt("CLASS{d}",
             .{class}), ttl, body }) }, true);
        if (section_index == 0) {
            h.append(h.Answer, &p.dns_answers, .{ .type_ = type_, .body = body });
            if (type_ == 1) p.set("dns.a", .{ .number = address }, true);
        }
    };
}

const std = @import("std");
const h = @import("hexdump.zig");
const net = @import("link_network.zig");
const Packet = h.Packet;
pub const mark_names = [_][]const u8{ "retransmission", "out_of_order", "lost_segment", "duplicate_ack" };
pub const Endpoint = struct {
    address: i64 = 0,
    port: i64 = 0,
    fn equal(a: Endpoint, b: Endpoint) bool {
        return a.address == b.address and a.port == b.port;
    }
};
pub const Side = struct { isn: ?i64 = null, mss: ?i64 = null, ws: ?i64 = null, base: ?i64 = null,
     expected: ?i64 = null, advanced: i64 = 0, packets: i64 = 0, payload: i64 = 0, intervals: std.AutoHashMapUnmanaged([2]i64,
     void) = .empty, previous_ack: ?[4]i64 = null, marks: [4]i64 = @splat(0) };
pub const Event = struct { packet: i64, side: usize, mark: usize, sequence: i64, length: i64 };
pub const State = struct { state: []const u8, packet: i64 };
pub const Stream = struct { client: Endpoint = .{}, server: Endpoint = .{}, state: []const u8 = "",
     history: std.ArrayList(State) = .empty, start: i64 = 0, end: i64 = 0, packets: i64 = 0, bytes: i64 = 0,
     f2: i64 = 0, handshake: [3]?i64 = @splat(null), sides: [2]Side = .{ .{}, .{} }, events: std.ArrayList(Event) = .empty,
     first_close: ?usize = null };
fn mod32(value: i64) i64 {
    return @mod(value, @as(i64, 1) << 32);
}
fn recordSyn(stream: *Stream, p: *Packet, side: usize) void {
    const s = &stream.sides[side];
    s.isn = p.num("tcp.seq_raw");
    s.mss = if (p.has("tcp.options.mss")) p.num("tcp.options.mss") else null;
    s.ws = if (p.has("tcp.options.wscale")) p.num("tcp.options.wscale") else null;
    stream.handshake[if (side == 0) @as(usize, 0) else 1] = p.number;
}
pub fn track(p: *Packet, streams: *std.ArrayList(Stream)) void {
    if (!p.has("tcp.srcport")) return;
    const source: Endpoint = .{ .address = p.num("ip.src"), .port = p.num("tcp.srcport") };
    const destination: Endpoint = .{ .address = p.num("ip.dst"), .port = p.num("tcp.dstport") };
    const syn = p.num("tcp.flags.syn") != 0;
    const ack_set = p.num("tcp.flags.ack") != 0;
    const fin = p.num("tcp.flags.fin") != 0;
    const rst = p.num("tcp.flags.rst") != 0;
    var index: ?usize = null;
    var i = streams.items.len;
    while (i > 0) {
        i -= 1;
        const stream = streams.items[i];
        if ((source.equal(stream.client) and destination.equal(stream.server)) or (destination.equal(stream.client) and source.equal(stream.server))) {
            index = i;
            break;
        }
    }
    if (index == null or ((h.eq(streams.items[index.?].state, "CLOSED") or h.eq(streams.items[index.?].state,
         "RESET")) and syn and !ack_set)) {
        var stream: Stream = .{ .start = p.time };
        if (syn and ack_set) {
            stream.client = destination;
            stream.server = source;
            stream.state = "SYN_RECEIVED";
            recordSyn(&stream, p, 1);
        } else {
            stream.client = source;
            stream.server = destination;
            stream.state = if (syn) "SYN_SENT" else "ESTABLISHED";
            if (syn) recordSyn(&stream, p, 0);
        }
        h.append(State, &stream.history, .{ .state = stream.state, .packet = p.number });
        index = streams.items.len;
        h.append(Stream, streams, stream);
    }
    const stream = &streams.items[index.?];
    p.put("tcp.stream", h.n(index.?));
    const side: usize = if (source.equal(stream.client)) 0 else 1;
    const s = &stream.sides[side];
    const other = &stream.sides[1 - side];
    const sequence = p.num("tcp.seq_raw");
    const ack = p.num("tcp.ack_raw");
    if (s.base == null) s.base = sequence;
    if (ack_set and other.base == null) other.base = ack;
    const relative = mod32(sequence - s.base.?);
    const length = p.num("tcp.len") + @as(i64, @intFromBool(syn)) + @as(i64, @intFromBool(fin));
    p.put("tcp.seq", relative);
    if (ack_set) p.put("tcp.ack", mod32(ack - other.base.?));
    var mark: ?usize = null;
    if (length > 0) {
        if (s.expected != null and relative > s.expected.?) mark = 2 else if (s.expected != null and relative < s.expected.?) mark = if (s.intervals.contains(.{ relative,
             length }) or p.time - s.advanced >= 3000) @as(usize, 0) else 1;
        s.intervals.put(h.allocator, .{ relative, length }, {}) catch @panic("allocation failed");
        if (s.expected == null or relative + length > s.expected.?) {
            s.expected = relative + length;
            s.advanced = p.time;
        }
    } else if (ack_set and !rst and s.previous_ack != null and s.previous_ack.?[0] == ack and s.previous_ack.?[1] == p.num("tcp.window")) {
        mark = 3;
        s.previous_ack.?[3] += 1;
        p.duplicate_origin = s.previous_ack.?[2];
        p.duplicate_count = s.previous_ack.?[3];
    }
    if (ack_set and (mark == null or mark.? != 3)) s.previous_ack = .{ ack, p.num("tcp.window"), p.number, 0 };
    if (mark) |m| {
        p.flag(h.fmt("tcp.analysis.{s}", .{mark_names[m]}));
        s.marks[m] += 1;
        h.append(Event, &stream.events, .{ .packet = p.number, .side = side, .mark = m, .sequence = relative, .length = length });
    }
    p.put("tcp.window.calc", p.num("tcp.window") * if (stream.sides[0].ws != null and stream.sides[1].ws != null and !syn) (@as(i64,
         1) << @as(u6, @intCast(s.ws.?))) else @as(i64, 1));
    const previous = stream.state;
    if (rst) {
        if (!h.eq(previous, "CLOSED") and !h.eq(previous, "RESET")) stream.state = "RESET";
    } else if (h.eq(previous, "SYN_SENT") and side == 1 and syn and ack_set and stream.sides[0].isn != null and ack == mod32(stream.sides[0].isn.? + 1)) {
        stream.state = "SYN_RECEIVED";
        recordSyn(stream, p, 1);
    } else if (h.eq(previous, "SYN_RECEIVED") and side == 0 and ack_set and !syn and stream.sides[1].isn != null and ack == mod32(stream.sides[1].isn.? + 1)) {
        stream.state = "ESTABLISHED";
        stream.handshake[2] = p.number;
    } else if (h.eq(previous, "ESTABLISHED") and fin) {
        stream.state = "FIN_WAIT";
        stream.first_close = side;
    } else if (h.eq(previous, "FIN_WAIT") and fin and side != stream.first_close.?) {
        stream.state = "CLOSING";
        stream.f2 = mod32(sequence + p.num("tcp.len") + 1);
    } else if (h.eq(previous, "CLOSING") and side == stream.first_close.? and ack_set and ack == stream.f2) stream.state = "CLOSED";
    if (!h.eq(stream.state, previous)) h.append(State, &stream.history, .{ .state = stream.state, .packet = p.number });
    s.packets += 1;
    s.payload += p.num("tcp.len");
    stream.packets += 1;
    stream.bytes += p.length;
    stream.end = p.time;
}
pub fn endpoint(value: Endpoint, port: bool) []const u8 {
    return if (port) h.fmt("{s}:{d}", .{ net.ipv4(value.address), value.port }) else net.ipv4(value.address);
}
pub const Conversation = struct { kind: usize, a: Endpoint, b: Endpoint, first: usize, start: i64,
     end: i64, packets: [2]i64 = @splat(0), bytes: [2]i64 = @splat(0) };
fn conversationLess(_: void, a: Conversation, b: Conversation) bool {
    const ab = a.bytes[0] + a.bytes[1];
    const bb = b.bytes[0] + b.bytes[1];
    const ap = a.packets[0] + a.packets[1];
    const bp = b.packets[0] + b.packets[1];
    return if (ab != bb) ab > bb else if (ap != bp) ap > bp else if (a.kind != b.kind) a.kind < b.kind else a.first < b.first;
}
pub fn conversations(packets: []const Packet) []Conversation {
    var result: std.ArrayList(Conversation) = .empty;
    for (packets, 0..) |p, packet_index| for (0..3) |kind| {
        if (!p.has(if (kind == 0) "ip.src" else if (kind == 1) "tcp.stream" else "udp.srcport")) continue;
        const source: Endpoint = .{ .address = p.num("ip.src"), .port = if (kind == 0) 0 else p.num(if (kind == 1) "tcp.srcport" else "udp.srcport") };
        const destination: Endpoint = .{ .address = p.num("ip.dst"), .port = if (kind == 0) 0 else p.num(if (kind == 1) "tcp.dstport" else "udp.dstport") };
        var found: ?usize = null;
        for (result.items, 0..) |c, i| if (c.kind == kind and ((source.equal(c.a) and destination.equal(c.b)) or (source.equal(c.b) and destination.equal(c.a))) and (kind != 1 or packets[c.first].num("tcp.stream") == p.num("tcp.stream"))) {
            found = i;
            break;
        };
        if (found == null) {
            found = result.items.len;
            h.append(Conversation, &result, .{ .kind = kind, .a = source, .b = destination, .first = packet_index,
                 .start = p.time, .end = p.time });
        }
        const c = &result.items[found.?];
        const side: usize = if (source.equal(c.a)) 0 else 1;
        c.packets[side] += 1;
        c.bytes[side] += p.length;
        c.end = p.time;
    };
    std.mem.sort(Conversation, result.items, {}, conversationLess);
    return result.items;
}
pub const EndpointTotals = struct { address: i64, packets: [2]i64 = @splat(0), bytes: [2]i64 = @splat(0) };
fn endpointLess(_: void, a: EndpointTotals, b: EndpointTotals) bool {
    const ab = a.bytes[0] + a.bytes[1];
    const bb = b.bytes[0] + b.bytes[1];
    const ap = a.packets[0] + a.packets[1];
    const bp = b.packets[0] + b.packets[1];
    return if (ab != bb) ab > bb else if (ap != bp) ap > bp else a.address < b.address;
}
pub fn endpoints(packets: []const Packet) []EndpointTotals {
    var result: std.ArrayList(EndpointTotals) = .empty;
    for (packets) |p| if (p.has("ip.src")) {
        for (0..2) |side| {
            const address = p.num(if (side == 0) "ip.src" else "ip.dst");
            var found: ?usize = null;
            for (result.items, 0..) |item, i| if (item.address == address) {
                found = i;
                break;
            };
            if (found == null) {
                found = result.items.len;
                h.append(EndpointTotals, &result, .{ .address = address });
            }
            result.items[found.?].packets[side] += 1;
            result.items[found.?].bytes[side] += p.length;
        }
    };
    std.mem.sort(EndpointTotals, result.items, {}, endpointLess);
    return result.items;
}

const std = @import("std");
pub var allocator: std.mem.Allocator = undefined;
pub const Integer = i64;
pub const DissectionError = error{Malformed};
pub fn alloc(comptime T: type, count: usize) []T {
    return allocator.alloc(T, count) catch @panic("allocation failed");
}
pub fn append(comptime T: type, list: *std.ArrayList(T), value: T) void {
    list.append(allocator, value) catch @panic("allocation failed");
}
pub fn fmt(comptime pattern: []const u8, args: anytype) []const u8 {
    return std.fmt.allocPrint(allocator, pattern, args) catch @panic("allocation failed");
}
pub fn eq(a: []const u8, b: []const u8) bool {
    return std.mem.eql(u8, a, b);
}
pub fn n(value: anytype) i64 {
    return @intCast(value);
}
pub fn u(value: i64) usize {
    return @intCast(value);
}
pub fn number(text: []const u8) i64 {
    return std.fmt.parseInt(i64, text, 10) catch unreachable;
}
pub fn split(text: []const u8, delimiter: u8) []const []const u8 {
    var out: std.ArrayList([]const u8) = .empty;
    var fields = std.mem.splitScalar(u8, text, delimiter);
    while (fields.next()) |value| append([]const u8, &out, value);
    return out.items;
}
pub fn join(values: []const []const u8, delimiter: []const u8) []const u8 {
    var text: Text = .{};
    for (values, 0..) |value, i| {
        if (i > 0) text.add("{s}", .{delimiter});
        text.add("{s}", .{value});
    }
    return text.value();
}
pub const Text = struct {
    data: std.ArrayList(u8) = .empty,
    pub fn add(self: *Text, comptime pattern: []const u8, args: anytype) void {
        self.data.appendSlice(allocator, fmt(pattern, args)) catch @panic("allocation failed");
    }
    pub fn value(self: Text) []const u8 {
        return self.data.items;
    }
};
pub const Lines = struct {
    data: std.ArrayList([]const u8) = .empty,
    pub fn add(self: *Lines, comptime pattern: []const u8, args: anytype) void {
        append([]const u8, &self.data, fmt(pattern, args));
    }
};
pub fn readLines(io: std.Io, path: []const u8) ![]const []const u8 {
    const text = try std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .unlimited);
    const lines = split(text, '\n');
    return lines[0 .. lines.len - 1];
}
pub fn writeLines(io: std.Io, name: []const u8, lines: Lines) !void {
    var text: Text = .{};
    for (lines.data.items) |line| text.add("{s}\n", .{line});
    try std.Io.Dir.cwd().createDirPath(io, "output");
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = fmt("output/{s}", .{name}), .data = text.value() });
}
pub fn seconds(value: i64) []const u8 {
    return fmt("{d}.{d:0>6}", .{ @divTrunc(value, 1000000), @mod(value, 1000000) });
}
pub fn decimal(value: i64) []const u8 {
    return fmt("{d}", .{value});
}
pub const Value = struct { number: i64 = 0, text: []const u8 = "" };
pub const Answer = struct { type_: i64, body: []const u8 };
pub const Packet = struct {
    number: i64 = 0,
    time: i64 = 0,
    length: i64 = 0,
    raw: []const u8 = &.{},
    remaining: []const u8 = &.{},
    reason: ?[]const u8 = null,
    layers: std.ArrayList([]const u8) = .empty,
    fields: std.StringHashMapUnmanaged(std.ArrayList(Value)) = .empty,
    dns_answers: std.ArrayList(Answer) = .empty,
    duplicate_origin: i64 = 0,
    duplicate_count: i64 = 0,
    pub fn set(self: *Packet, name: []const u8, value: Value, multiple: bool) void {
        const entry = self.fields.getOrPut(allocator, name) catch @panic("allocation failed");
        if (!entry.found_existing) entry.value_ptr.* = .empty;
        if (!multiple) entry.value_ptr.items.len = 0;
        append(Value, entry.value_ptr, value);
    }
    pub fn put(self: *Packet, name: []const u8, value: i64) void {
        self.set(name, .{ .number = value }, false);
    }
    pub fn text(self: *Packet, name: []const u8, value: []const u8) void {
        self.set(name, .{ .text = value }, false);
    }
    pub fn flag(self: *Packet, name: []const u8) void {
        self.put(name, 0);
    }
    pub fn values(self: Packet, name: []const u8) []const Value {
        return if (self.fields.get(name)) |values_| values_.items else &.{};
    }
    pub fn has(self: Packet, name: []const u8) bool {
        return self.values(name).len > 0;
    }
    pub fn num(self: Packet, name: []const u8) i64 {
        const list = self.values(name);
        return if (list.len > 0) list[0].number else 0;
    }
    pub fn str(self: Packet, name: []const u8) []const u8 {
        const list = self.values(name);
        return if (list.len > 0) list[0].text else "";
    }
    pub fn fail(self: *Packet, reason: []const u8) DissectionError {
        self.reason = reason;
        return error.Malformed;
    }
};
fn lowerHex(c: u8) bool {
    return (c >= '0' and c <= '9') or (c >= 'a' and c <= 'f');
}
fn wellFormed(text: []const u8) bool {
    if (text.len < 8 or text.len > 53 or (text.len - 8) % 3 != 0 or text[4] != ' ' or text[5] != ' ') return false;
    for (text[0..4]) |c| if (!lowerHex(c)) return false;
    var i: usize = 6;
    while (i < text.len) : (i += 3) {
        if (!lowerHex(text[i]) or !lowerHex(text[i + 1]) or (i + 2 < text.len and text[i + 2] != ' ')) return false;
    }
    return true;
}
fn finish(packet: *Packet) void {
    if (packet.reason == null and n(packet.raw.len) != packet.length) packet.reason = fmt("dump: length mismatch (header {d}, data {d})",
         .{ packet.length, packet.raw.len });
}
pub fn readCapture(io: std.Io) ![]Packet {
    const lines = try readLines(io, "input/capture.txt");
    var packets: std.ArrayList(Packet) = .empty;
    var raw: std.ArrayList(u8) = .empty;
    for (lines, 1..) |line, line_number| {
        if (std.mem.startsWith(u8, line, "PACKET ")) {
            if (packets.items.len > 0) finish(&packets.items[packets.items.len - 1]);
            const fields = split(line, ' ');
            append(Packet, &packets, .{ .number = number(fields[1]), .time = number(fields[2]), .length = number(fields[3]) });
            raw = .empty;
            continue;
        }
        const packet = &packets.items[packets.items.len - 1];
        if (line.len == 0 or packet.reason != null) continue;
        if (!wellFormed(line)) {
            packet.reason = fmt("dump: bad line {d}", .{line_number});
            continue;
        }
        const offset = std.fmt.parseInt(usize, line[0..4], 16) catch unreachable;
        if (offset != raw.items.len) {
            packet.reason = fmt("dump: offset mismatch at line {d}", .{line_number});
            continue;
        }
        var i: usize = 6;
        while (i < line.len) : (i += 3) append(u8, &raw, std.fmt.parseInt(u8, line[i .. i + 2], 16) catch unreachable);
        packet.raw = raw.items;
    }
    finish(&packets.items[packets.items.len - 1]);
    return packets.items;
}
pub fn dumpLines(data: []const u8) Lines {
    var out: Lines = .{};
    var start: usize = 0;
    while (start < data.len) : (start += 16) {
        var bytes: Text = .{};
        var characters: Text = .{};
        for (data[start..@min(start + 16, data.len)], 0..) |byte, i| {
            bytes.add("{s}{x:0>2}", .{ if (i == 0) "" else " ", byte });
            characters.add("{c}", .{if (byte >= 32 and byte <= 126) byte else @as(u8, '.')});
        }
        out.add("{x:0>4}  {s: <47}  |{s}|", .{ start, bytes.value(), characters.value() });
    }
    return out;
}

const h = @import("hexdump.zig");
const Packet = h.Packet;
pub fn integer(data: []const u8, position: usize, count: usize) i64 {
    var value: i64 = 0;
    for (data[position .. position + count]) |byte| value = value * 256 + byte;
    return value;
}
pub fn checksum(data: []const u8) []const u8 {
    var sum: i64 = 0;
    var i: usize = 0;
    while (i < data.len) : (i += 2) sum += @as(i64, data[i]) * 256 + if (i + 1 < data.len) @as(i64, data[i + 1]) else 0;
    while (sum > 65535) sum = (sum & 65535) + (sum >> 16);
    return if (sum == 65535) "good" else "bad";
}
pub fn mac(address: i64) []const u8 {
    var parts: [6][]const u8 = undefined;
    for (&parts, 0..) |*part, i| part.* = h.fmt("{x:0>2}", .{(address >> @as(u6, @intCast((5 - i) * 8))) & 255});
    return h.join(&parts, ":");
}
pub fn ipv4(address: i64) []const u8 {
    return h.fmt("{d}.{d}.{d}.{d}", .{ (address >> 24) & 255, (address >> 16) & 255, (address >> 8) & 255, address & 255 });
}
pub fn ethernet(p: *Packet, b: []const u8) h.DissectionError![]const u8 {
    if (b.len < 14) return p.fail("eth: truncated");
    p.put("eth.dst", integer(b, 0, 6));
    p.put("eth.src", integer(b, 6, 6));
    p.put("eth.type", integer(b, 12, 2));
    return b[14..];
}
pub fn arp(p: *Packet, b: []const u8) h.DissectionError!void {
    if (b.len < 28) return p.fail("arp: truncated");
    if (integer(b, 0, 2) != 1 or integer(b, 2, 2) != 2048 or b[4] != 6 or b[5] != 4) return p.fail("arp: unsupported format");
    p.put("arp.opcode", integer(b, 6, 2));
    p.put("arp.src.hw", integer(b, 8, 6));
    p.put("arp.src.ip", integer(b, 14, 4));
    p.put("arp.dst.hw", integer(b, 18, 6));
    p.put("arp.dst.ip", integer(b, 24, 4));
}
pub fn internet(p: *Packet, b: []const u8) h.DissectionError![]const u8 {
    if (b.len < 20) return p.fail("ip: truncated header");
    const version = b[0] / 16;
    const header = @as(usize, b[0] % 16) * 4;
    if (version != 4) return p.fail(h.fmt("ip: bad version {d}", .{version}));
    if (header < 20) return p.fail(h.fmt("ip: bad header length {d}", .{header}));
    if (b.len < header) return p.fail("ip: truncated header");
    const total = h.u(integer(b, 2, 2));
    const flags = integer(b, 6, 2);
    if (total < header) return p.fail(h.fmt("ip: bad total length {d}", .{total}));
    if (total > b.len) return p.fail(h.fmt("ip: truncated (total length {d}, available {d})", .{ total, b.len }));
    p.put("ip.hdr_len", h.n(header));
    p.put("ip.tos", b[1]);
    p.put("ip.len", h.n(total));
    p.put("ip.id", integer(b, 4, 2));
    p.put("ip.flags.df", (flags >> 14) & 1);
    p.put("ip.flags.mf", (flags >> 13) & 1);
    p.put("ip.frag_offset", @mod(flags, 8192) * 8);
    p.put("ip.ttl", b[8]);
    p.put("ip.proto", b[9]);
    p.put("ip.checksum", integer(b, 10, 2));
    p.text("ip.checksum.status", checksum(b[0..header]));
    p.put("ip.src", integer(b, 12, 4));
    p.put("ip.dst", integer(b, 16, 4));
    if (p.num("ip.flags.mf") != 0 or p.num("ip.frag_offset") != 0) p.flag("ip.fragment");
    return b[header..total];
}

